 app.post('/v1/voice/call',async(req,reply)=>{const body=req.body as any,initialScope=scopeFor(req,false),initialEpoch=initialScope.epoch,owner=principals.get(req)!;const live=()=>initialScope.epoch===initialEpoch&&!initialScope.controller.signal.aborted;if(typeof body.sdp!=='string'||body.sdp.length>100000)throw new CapriError('Invalid voice offer.');if(await assistant.router.selected()==='local')return {mode:'local'};if(!options.key())throw new CapriError('Connect OpenAI first.',503);let reservation:any;try{reservation=await assistant.reserve('voice',1);}catch(e:any){if(e.status===402&&(await settings()).localFallback){await assistant.router.block('Monthly application allowance reached.','application_budget_exceeded');return {mode:'local'};}throw e;}if(!live()){await assistant.settle(reservation.id,0);throw new CapriError('Voice session ended.',409);}const config=await settings();const form=new FormData();form.set('sdp',body.sdp);form.set('session',JSON.stringify({type:'realtime',model:config.voiceModel,instructions:characterProfile(config)+' You can talk and explain. For actions, plans, current research, and memories, call request_task. Never claim tools ran without a returned result.',max_output_tokens:512,audio:{input:{turn_detection:{type:'server_vad',create_response:true,interrupt_response:true},transcription:{model:'gpt-transcribe'}},output:{voice:config.voice}},tools:[{type:'function',name:'request_task',description:'Ask Capri’s permissioned task service to carry out a request.',parameters:{type:'object',properties:{text:{type:'string'}},required:['text']}}],tool_choice:'auto'}));let response:Response;try{response=await fetch('https://api.openai.com/v1/realtime/calls',{method:'POST',headers:{Authorization:'Bearer '+options.key()},body:form,signal:AbortSignal.timeout(20000)});}catch(e){await assistant.settle(reservation.id);throw e;}if(!response.ok){await assistant.settle(reservation.id,0);const data=await response.json().catch(()=>({})) as any;const error=new ProviderError(data.error?.message||'Voice connection failed: HTTP '+response.status,response.status,data.error?.code||'',data.error?.type||'');if(exhausted(error)&&(await settings()).localFallback){await assistant.router.block('OpenAI voice allowance reached.',error.code);return {mode:'local'};}throw error;}const sdp=await response.text();const callId=response.headers.get('location')?.split('/').pop();if(!callId){await assistant.settle(reservation.id);throw new CapriError('Voice provider did not return a controllable call.');}if(!live()){await Promise.allSettled([fetch('https://api.openai.com/v1/realtime/calls/'+encodeURIComponent(callId)+'/hangup',{method:'POST',headers:{Authorization:'Bearer '+options.key()},signal:AbortSignal.timeout(10000)}),assistant.settle(reservation.id)]);throw new CapriError('Voice session ended.',409);}voiceSessions.set(callId,{privateSession:body.private===true||initialScope.privateSession,owner,epoch:initialEpoch,seen:new Set()});const stop=async()=>{clearTimeout(timer);voiceCalls.delete(callId);voiceSessions.delete(callId);await Promise.allSettled([fetch('https://api.openai.com/v1/realtime/calls/'+encodeURIComponent(callId)+'/hangup',{method:'POST',headers:{Authorization:'Bearer '+options.key()},signal:AbortSignal.timeout(10000)}),assistant.settle(reservation.id)]);};const timer=setTimeout(()=>void stop(),120000);voiceCalls.set(callId,stop);return {sdp,callId,maxSeconds:120};});
 app.post('/v1/voice/transcript',async req=>{const body=req.body as any;const session=voiceSessions.get(String(body.callId));if(!session||session.owner!==principals.get(req)||sessionScopes.get(session.owner)?.epoch!==session.epoch)throw new CapriError('Voice session ended.',409);if(session.privateSession)return {saved:false,private:true};if(!['user','assistant'].includes(body.role))throw new CapriError('Invalid transcript role.');const id=cleanText(body.id,200);const text=cleanText(body.text,12000);if(session.seen.has(id))return {saved:true,duplicate:true};session.seen.add(id);try{await store.put('message',{id:hash(body.callId+':'+id),role:body.role,text,source:'voice',callId:body.callId});emit({type:'changed',kind:'message'});return {saved:true};}catch(e){session.seen.delete(id);throw e;}});
